"""Frozen synthetic training matrix. Held-out observations are generated by score.py."""

import argparse
from functools import lru_cache
import os
from pathlib import Path
import sys
from time import perf_counter, process_time

ROOT = Path(__file__).resolve().parents[2]
sys.path[:0] = [str(ROOT), str(ROOT/'src')]
for env_name in ('OMP_NUM_THREADS', 'MKL_NUM_THREADS', 'OPENBLAS_NUM_THREADS'):
    os.environ[env_name] = '1'

import numpy as np
import torch

from experiments.osgkd_v2_sprint2a_20261125 import resume_host as io
from experiments.osgkd_v2_wp2_layer1_20261127 import controls, engine, models, probe, synthetic, training
from kiki.data.osgkd_synthetic import model_constants, motion_packet


RUN = probe.RUN
LOCAL = ROOT/'artifacts'/RUN/'fit'
PUBLIC = ROOT/'results'/RUN
PRIMARY, REPEAT = 24121, 24122
DENSE, REFIT, ADAPT = 128, 128, 128
HORIZON, BATCH = 400, 4
NOISES = tuple(synthetic.noise_key(level) for level in synthetic.NOISE_LEVELS)
REQUIRED_SOURCES = probe.REQUIRED_SOURCES | controls.SOURCES | {
    *('experiments/' + RUN + '/' + name for name in
      ('negative_controls.py', 'recovery.py', 'training.py', 'run.py', 'score.py')),
}


def n8_cases():
    return ([(condition, noise, PRIMARY) for condition in synthetic.CONDITIONS for noise in NOISES]
            + [('open', '0.01', REPEAT)])


def expected_matrix():
    return [dict(n=8, condition=condition, noise=noise, seed=seed, methods=list(models.METHODS))
            for condition, noise, seed in n8_cases()] + [
        dict(n=n, condition='open', noise='0.01', seed=seed,
             methods=['same_template', 'ode_adapt', 'frozen_lift'])
        for n in (16, 32) for seed in (PRIMARY, REPEAT)]


def resource_batch(dry):
    result = {}
    for n in probe.SIZES:
        eligible = [row['batch_size'] for row in dry['cells'] if row['n'] == n and row['prediction_s'] == 4.
                    and row['status'] == 'completed'
                    and row['peak_rss_bytes'] <= .75 * row['system_memory_before']['physical_available_bytes']]
        io.require(eligible, f'4 s resource budget not qualified at N={n}')
        result[str(n)] = max(eligible)
    return result


def validate(release_path):
    value = io.read(release_path)
    io.require(release_path == PUBLIC/'release.json' and value['run_id'] == RUN and value['released'] is True,
               'canonical WP2 fit release required')
    io.require(Path(sys.executable).resolve() == (ROOT.parent/'.venv/Scripts/python.exe').resolve(),
               'shared Python environment required')
    io.require(REQUIRED_SOURCES <= set(value['source_hashes']), 'missing WP2 source hashes')
    for name, sha in value['source_hashes'].items():
        path = (ROOT/name).resolve()
        io.require(path.is_relative_to(ROOT) and io.identity(path)['sha256'] == sha, 'source differs: '+name)
    io.require(value['scientist']['configured_model'] == 'gpt-6-astra' and value['independent_preflight']['status'] == 'passed',
               'actual scientist and preflight required')
    io.require(value['jobs'] == expected_matrix() and value['update_budgets'] == dict(dense=DENSE, refit=REFIT, adapt=ADAPT)
               and value['new_fom'] == 0 and value['test_trajectory_access'] is False
               and value['default_model'] == 'none', 'registered synthetic budget differs')
    dry = io.read(io.verified(value['dry_summary']))
    io.require(dry['run_id'] == RUN and dry['status'] == 'completed' and dry['updates'] == 0
               and dry['new_fom'] == 0 and not dry['test_trajectory_access'] and len(dry['cells']) == 18,
               'dry-run provenance or coverage differs')
    io.require(value['microbatch_by_n'] == resource_batch(dry), 'resource choice differs')
    negative = io.read(io.verified(value['controls']))
    io.require(negative['run_id']==RUN and negative['status']=='completed' and negative['updates']==0
               and negative['test_trajectory_access'] is False and negative['ieee39_event_access'] is False,
               'frozen analytic controls required')
    previous = io.read(io.verified(value['wp1a_closed']))
    io.require(previous['run_id'] == 'osgkd_v2_wp1a_refits_20261127'
               and previous['execution']['status'] == 'COMPLETED', 'WP1A must finish before synthetic optimization')
    return value


def cell_key(n, condition, noise, seed):
    return f'n{n}_{condition}_noise{noise}_s{seed}'


@lru_cache(maxsize=2)
def train_observations(n, condition):
    system = synthetic.make_system(n=n, condition=condition)
    levels = synthetic.NOISE_LEVELS if n == 8 else (.01,)
    by_noise = {synthetic.noise_key(level): [] for level in levels}
    mesh = []
    for i in range(48):
        seed, excitation = synthetic.TRAIN_SEED + i, synthetic.EXCITATIONS[i//12]
        events, coarse = synthetic.generate_episode(system, seed, excitation, noise_levels=levels)
        _, fine = synthetic.generate_episode(system, seed, excitation, noise_levels=(0.,), internal_dt=.00125)
        mesh.append(float(np.max(np.abs(coarse['state'] - fine['state']))))
        for key in by_noise:
            by_noise[key].append(events[key])
    io.require(max(mesh) <= 1e-6, 'truth training integration grids disagree')
    constants = model_constants(motion_packet(next(iter(by_noise.values()))[0]))
    return by_noise, constants, max(mesh)


def support_summary(support):
    if support is None:
        return None
    return dict(base=support.base.tolist(), modulation=support.modulation.tolist())


def support_from_summary(value):
    if value is None:
        return None
    return models.EdgeSupport(torch.tensor(value['base'], dtype=torch.bool),
                              torch.tensor(value['modulation'], dtype=torch.bool))


def train_support(model, episodes, microbatch):
    rms = engine.function_rms(model, episodes, HORIZON, microbatch)
    if rms is None:
        return None, None
    return models.threshold_support(rms), rms.tolist()


def saved_state(model, receipt):
    io.require(receipt['status'] == 'completed' and receipt['checkpoint'], 'fixed endpoint required')
    training.restore(receipt['checkpoint'], model)
    return model


def train_method(method, folder, binding, events, ep, constants, seed, microbatch):
    model = models.make_model(method, constants, seed)
    weak = models.weak_force_fit(events, model, HORIZON) if method == 'weak_static' else None
    order = engine.plan(len(ep), BATCH, DENSE+REFIT, seed)
    prefix, suffix = order[:DENSE], order[DENSE:]
    dense = training.fit_stage(model, ep, folder/'dense', {**binding, 'stage':'dense'}, prefix, HORIZON, microbatch)
    result = dict(method=method, dense=dense, variant_results={}, weak_refit=weak)
    if dense['status'] != 'completed':
        return result
    selection, rms = train_support(model, ep, microbatch) if method == 'osgkd' else (None, None)
    result.update(dense_selected_support=support_summary(selection), dense_function_rms=rms)
    for variant in ('full', 'sparse') if method == 'osgkd' else ('full',):
        training.restore(dense['checkpoint'], model)
        masks = selection.masks(model) if variant == 'sparse' else {}
        models.project(model, masks)
        phase = {**binding, 'stage': 'refit', 'variant': variant, 'parent': dense['checkpoint'],
                 'mask': support_summary(selection) if variant == 'sparse' else None}
        fit = training.fit_stage(model, ep, folder/variant, phase, suffix, HORIZON, microbatch, masks)
        if fit['status'] == 'completed':
            active, end_rms = train_support(model.eval(), ep, microbatch)
            used = selection if variant == 'sparse' else active
            fit.update(support=support_summary(used), active_support=support_summary(active), end_function_rms=end_rms)
        result['variant_results'][variant] = fit
    return result


def target_fit(mode, folder, binding, source_model, source_fit, ep, constants, seed, microbatch):
    binding = {**binding, 'stage': mode}
    if mode == 'same_template':
        model = models.make_model('osgkd', constants, seed)
        order = engine.plan(len(ep), BATCH, DENSE+REFIT, seed)
        fit = training.fit_stage(model, ep, folder, binding, order, HORIZON, microbatch)
    elif source_fit is None:
        return dict(status='source_endpoint_unavailable', attempts=0, accepted=0, checkpoint=None, binding=binding)
    else:
        model = models.lifted_model(source_model, constants, seed)
        lift = synthetic.full_offset_lift(model.n//source_model.n)
        node_source = lift['node_source']
        src_state = torch.linspace(-.3, .5, steps=5*source_model.n, dtype=torch.float64).reshape(5, -1)
        with torch.no_grad():
            lifted_rhs = model.rhs(None, src_state[:, node_source].flatten()).reshape(5, -1)
            source_rhs = source_model.rhs(None, src_state.flatten()).reshape(5, -1)[:, node_source]
            gap = float((lifted_rhs - source_rhs).abs().max())
        io.require(gap <= 1e-12, 'frozen lift failed on synchronized clone state')
        if mode == 'frozen_lift':
            folder.mkdir(parents=True, exist_ok=True)
            path = folder/'frozen.pt'
            if path.exists():
                ref = io.identity(path)
                saved = torch.load(io.verified(ref), map_location='cpu', weights_only=True)
                io.require(saved['binding'] == binding and all(torch.equal(saved['state'][k], v)
                           for k,v in model.state_dict().items()), 'saved frozen lift differs')
            else:
                ref = training.seal(path, dict(state=model.state_dict(), binding=binding))
            mapped = torch.as_tensor(lift['edge_source'])
            source_support = support_from_summary(source_fit['support'])
            kept = mapped >= 0
            idx = mapped.clamp_min(0)
            support = models.EdgeSupport(kept & source_support.base[idx], kept & source_support.modulation[idx])
            return dict(status='completed', attempts=0, accepted=0, checkpoint=ref, binding=binding,
                        support=support_summary(support), source_checkpoint=source_fit['checkpoint'],
                        synchronized_clone_rhs_gap=gap, used_target_train=False, wall_s=0., cpu_s=0.)
        model.encoder.requires_grad_(False)
        order = engine.plan(len(ep), BATCH, ADAPT, seed)
        fit = training.fit_stage(model, ep, folder, {**binding, 'parent': source_fit['checkpoint']},
                                 order, HORIZON, microbatch)
        fit.update(source_checkpoint=source_fit['checkpoint'], synchronized_clone_rhs_gap=gap)
    if fit['status'] == 'completed':
        support, rms = train_support(model.eval(), ep, microbatch)
        fit.update(support=support_summary(support), end_function_rms=rms, used_target_train=True)
    return fit


def execute(path):
    release = validate(path)
    authority = io.identity(path)
    torch.set_num_threads(1)
    LOCAL.mkdir(parents=True, exist_ok=True)
    lock = LOCAL/'writer.lock'
    with lock.open('x') as f:
        f.write(str(os.getpid()))
    begin, cpu = perf_counter(), process_time()
    completed = {}
    try:
        for job in release['jobs']:
            n, condition, noise, seed = (job[k] for k in ('n', 'condition', 'noise', 'seed'))
            key = cell_key(n, condition, noise, seed)
            microbatch = release['microbatch_by_n'][str(n)]
            observations, constants, mesh = train_observations(n, condition)
            events = observations[noise]
            ep = engine.Episodes.from_events(events)
            folder = LOCAL/key
            folder.mkdir(parents=True, exist_ok=True)
            refs = {}
            for method in job['methods']:
                result_path = folder/(method+'_summary.json')
                binding = dict(release=authority, cell=job, cell_key=key, method=method)
                io.write(LOCAL/'live.json', dict(cell=key, method=method, pid=os.getpid(), utc=io.utc()))
                if result_path.exists():
                    io.require(io.read(result_path)['binding'] == binding, 'completed method binding differs')
                elif n == 8:
                    result = train_method(method, folder/method, binding, events, ep, constants, seed, microbatch)
                    io.write(result_path, {**result, 'binding': binding})
                else:
                    source_key = cell_key(8, 'open', '0.01', seed)
                    source = io.read(io.verified(completed[source_key]['methods']['osgkd']))
                    candidate = source['variant_results'].get('full')
                    source_fit = candidate if candidate and candidate['status'] == 'completed' else None
                    source_model = None
                    if source_fit:
                        _, source_constants, _ = train_observations(8, 'open')
                        source_model = saved_state(models.make_model('osgkd', source_constants, seed), source_fit)
                    result = target_fit(method, folder/method, binding, source_model, source_fit, ep, constants, seed, microbatch)
                    io.write(result_path, dict(result=result, binding=binding))
                refs[method] = io.identity(result_path)
                print(key, method, refs[method]['sha256'], flush=True)
            completed[key] = dict(job=job, methods=refs, train_count=len(ep), truth_mesh_gap=mesh)
        result = dict(run_id=RUN, status='completed', release=authority, cells=completed,
                      controls=release['controls'], ieee39_event_access=False,
                      synthetic_val_access=False, test_trajectory_access=False, new_fom=0,
                      wall_s=perf_counter()-begin, cpu_s=process_time()-cpu, completed_utc=io.utc())
        io.write(PUBLIC/'fit_summary.json', result)
        io.write(LOCAL/'live.json', dict(status='completed', pid=os.getpid(), utc=io.utc()))
    except BaseException as error:
        io.write(LOCAL/f'failed_{os.getpid()}.json', dict(error=repr(error), release=authority, utc=io.utc()))
        raise
    else:
        lock.unlink()


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--release', required=True, type=Path)
    execute(parser.parse_args().release.resolve())
